inline bool VerifySpawnConditionU(::flatbuffers::Verifier &verifier, const void *obj, SpawnConditionU type) {
  switch (type) {
    case SpawnConditionU::NONE: {
      return true;
    }
    case SpawnConditionU::FocusNear: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::FocusNear *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case SpawnConditionU::TagNear: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::TagNear *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case SpawnConditionU::AtTime: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::AtTime *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case SpawnConditionU::WorldFlag: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::WorldFlag *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifySpawnConditionUVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<SpawnConditionU> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifySpawnConditionU(
        verifier,  values->Get(i), types->GetEnum<SpawnConditionU>(i))) {
      return false;
    }
  }
  return true;
}

inline void *SpawnConditionUUnion::UnPack(const void *obj, SpawnConditionU type, const ::flatbuffers::resolver_function_t *resolver) {
  (void)resolver;
  switch (type) {
    case SpawnConditionU::FocusNear: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::FocusNear *>(obj);
      return ptr->UnPack(resolver);
    }
    case SpawnConditionU::TagNear: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::TagNear *>(obj);
      return ptr->UnPack(resolver);
    }
    case SpawnConditionU::AtTime: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::AtTime *>(obj);
      return ptr->UnPack(resolver);
    }
    case SpawnConditionU::WorldFlag: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::WorldFlag *>(obj);
      return ptr->UnPack(resolver);
    }
    default: return nullptr;
  }
}

inline ::flatbuffers::Offset<void> SpawnConditionUUnion::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const ::flatbuffers::rehasher_function_t *_rehasher) const {
  (void)_rehasher;
  switch (type) {
    case SpawnConditionU::FocusNear: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::FocusNearT *>(value);
      return CreateFocusNear(_fbb, ptr, _rehasher).Union();
    }
    case SpawnConditionU::TagNear: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::TagNearT *>(value);
      return CreateTagNear(_fbb, ptr, _rehasher).Union();
    }
    case SpawnConditionU::AtTime: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::AtTimeT *>(value);
      return CreateAtTime(_fbb, ptr, _rehasher).Union();
    }
    case SpawnConditionU::WorldFlag: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::WorldFlagT *>(value);
      return CreateWorldFlag(_fbb, ptr, _rehasher).Union();
    }
    default: return 0;
  }
}

inline SpawnConditionUUnion::SpawnConditionUUnion(const SpawnConditionUUnion &u) : type(u.type), value(nullptr) {
  switch (type) {
    case SpawnConditionU::FocusNear: {
      value = new SE::FlatBuffers::FocusNearT(*reinterpret_cast<SE::FlatBuffers::FocusNearT *>(u.value));
      break;
    }
    case SpawnConditionU::TagNear: {
      value = new SE::FlatBuffers::TagNearT(*reinterpret_cast<SE::FlatBuffers::TagNearT *>(u.value));
      break;
    }
    case SpawnConditionU::AtTime: {
      value = new SE::FlatBuffers::AtTimeT(*reinterpret_cast<SE::FlatBuffers::AtTimeT *>(u.value));
      break;
    }
    case SpawnConditionU::WorldFlag: {
      value = new SE::FlatBuffers::WorldFlagT(*reinterpret_cast<SE::FlatBuffers::WorldFlagT *>(u.value));
      break;
    }
    default:
      break;
  }
}

inline void SpawnConditionUUnion::Reset() {
  switch (type) {
    case SpawnConditionU::FocusNear: {
      auto ptr = reinterpret_cast<SE::FlatBuffers::FocusNearT *>(value);
      delete ptr;
      break;
    }
    case SpawnConditionU::TagNear: {
      auto ptr = reinterpret_cast<SE::FlatBuffers::TagNearT *>(value);
      delete ptr;
      break;
    }
    case SpawnConditionU::AtTime: {
      auto ptr = reinterpret_cast<SE::FlatBuffers::AtTimeT *>(value);
      delete ptr;
      break;
    }
    case SpawnConditionU::WorldFlag: {
      auto ptr = reinterpret_cast<SE::FlatBuffers::WorldFlagT *>(value);
      delete ptr;
      break;
    }
    default: break;
  }
  value = nullptr;
  type = SpawnConditionU::NONE;
}

